CREATE TABLE IF NOT EXISTS tokens (token VARCHAR(64) PRIMARY KEY, expires BIGINT NOT NULL, role VARCHAR(20) NOT NULL DEFAULT 'CANDIDATE');
ALTER TABLE tokens ADD COLUMN IF NOT EXISTS role VARCHAR(20) NOT NULL DEFAULT 'CANDIDATE';
CREATE TABLE IF NOT EXISTS questions (id VARCHAR(80) PRIMARY KEY, kind VARCHAR(40), text VARCHAR(4000), choices VARCHAR(4000));
INSERT INTO questions (id,kind,text,choices) SELECT 'q1','MCQ','Which data structure offers average O(1) lookup?','["Linked List","HashMap","Binary Search Tree","Array"]' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE id='q1');
INSERT INTO questions (id,kind,text,choices) SELECT 'q2','TECHNICAL','How would you design a resilient Spring Boot REST API for high traffic?','[]' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE id='q2');
CREATE TABLE IF NOT EXISTS sessions (id VARCHAR(80) PRIMARY KEY, owner VARCHAR(64), state VARCHAR(30), consent BOOLEAN, consent_at BIGINT, checks CLOB, questions CLOB, deadline BIGINT, submitted_at BIGINT);
ALTER TABLE sessions ADD COLUMN IF NOT EXISTS started_at BIGINT;
ALTER TABLE sessions ADD COLUMN IF NOT EXISTS evidence_consent BOOLEAN NOT NULL DEFAULT FALSE;
CREATE TABLE IF NOT EXISTS answers (session_id VARCHAR(80) REFERENCES sessions(id), question_id VARCHAR(80), answer CLOB, PRIMARY KEY(session_id,question_id));
CREATE TABLE IF NOT EXISTS reviews (session_id VARCHAR(80) PRIMARY KEY REFERENCES sessions(id), reviewer VARCHAR(64) NOT NULL, score INT NOT NULL, notes CLOB NOT NULL, recommendation VARCHAR(20), reviewed_at BIGINT NOT NULL);
ALTER TABLE reviews ADD COLUMN IF NOT EXISTS recommendation VARCHAR(20);
CREATE TABLE IF NOT EXISTS integrity_evidence (id VARCHAR(80) PRIMARY KEY, session_id VARCHAR(80) NOT NULL REFERENCES sessions(id), event_type VARCHAR(40) NOT NULL, media_type VARCHAR(20) NOT NULL, captured_at BIGINT NOT NULL, expires_at BIGINT NOT NULL, content_type VARCHAR(40) NOT NULL, image BLOB NOT NULL);
ALTER TABLE tokens ADD COLUMN IF NOT EXISTS account_id VARCHAR(80);
ALTER TABLE tokens ADD COLUMN IF NOT EXISTS invitation_id VARCHAR(80);
ALTER TABLE questions ADD COLUMN IF NOT EXISTS recruiter_id VARCHAR(80);
CREATE TABLE IF NOT EXISTS recruiters (id VARCHAR(80) PRIMARY KEY, email VARCHAR(254) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, password_hash VARCHAR(512) NOT NULL);
CREATE TABLE IF NOT EXISTS interviews (id VARCHAR(80) PRIMARY KEY, recruiter_id VARCHAR(80) NOT NULL REFERENCES recruiters(id), title VARCHAR(200) NOT NULL, description VARCHAR(4000) NOT NULL, duration_seconds INT NOT NULL, scheduled_at BIGINT NOT NULL, questions CLOB NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS invitations (id VARCHAR(80) PRIMARY KEY, interview_id VARCHAR(80) NOT NULL REFERENCES interviews(id), candidate_name VARCHAR(120) NOT NULL, candidate_email VARCHAR(254) NOT NULL, code_hash VARCHAR(64) NOT NULL UNIQUE, expires_at BIGINT NOT NULL, session_id VARCHAR(80), created_at BIGINT NOT NULL);
ALTER TABLE sessions ADD COLUMN IF NOT EXISTS interview_id VARCHAR(80);
ALTER TABLE sessions ADD COLUMN IF NOT EXISTS invitation_id VARCHAR(80);
ALTER TABLE sessions ADD COLUMN IF NOT EXISTS duration_seconds INT;
ALTER TABLE invitations ADD COLUMN IF NOT EXISTS encrypted_code CLOB;
ALTER TABLE sessions ADD COLUMN IF NOT EXISTS submission_reason VARCHAR(30);
CREATE INDEX IF NOT EXISTS sessions_expiry_idx ON sessions(state,deadline);
CREATE INDEX IF NOT EXISTS sessions_review_list_idx ON sessions(state,submitted_at,id);
